import{_ as i,o as t,c as l,b3 as o}from"./chunks/framework.VnelH-cX.js";const r="/docs-imgs/main-window.webp",n="/docs-imgs/guide/SnowShot_2025-10-28_01-23-01.webp",e="/docs-imgs/guide/SnowShot_2025-10-28_01-23-36.webp",s="/docs-imgs/tray-menu.webp",q=JSON.parse('{"title":"快速入门","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786700458000}'),h={name:"guide/index.md"};function g(d,a,p,u,c,m){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="快速入门" tabindex="-1">快速入门 <a class="header-anchor" href="#快速入门" aria-label="Permalink to &quot;快速入门&quot;">​</a></h1><p>Wing Shot 追求简单高效的使用体验，希望每个用户都能依照直觉无痛使用。本指南将帮助您快速掌握 Wing Shot 的核心功能和使用技巧。</p><h2 id="打开主界面" tabindex="-1">打开主界面 <a class="header-anchor" href="#打开主界面" aria-label="Permalink to &quot;打开主界面&quot;">​</a></h2><p>参照<a href="/download/">下载安装</a>完成 Wing Shot 的安装后，使用鼠标右键点击应用托盘打开<strong>托盘菜单</strong>，点击<strong>显示主界面</strong>即可打开应用的主界面。</p><p><img src="'+r+'" alt="主界面"></p><p>主界面默认打开<strong>快捷功能</strong>页面，在快捷功能页面能快速预览 Wing Shot 的关键功能。</p><p>每个快捷功能都通过按钮展示，点击每个按钮都能响应对应的应用功能。</p><p>点击某个功能的右侧按钮，可以自定义配置功能的全局快捷键，以便快速唤起应用功能。</p><p><img src="'+n+'" alt="快捷功能"><img src="'+e+'" alt="按键设置"></p><h2 id="基础截图操作" tabindex="-1">基础截图操作 <a class="header-anchor" href="#基础截图操作" aria-label="Permalink to &quot;基础截图操作&quot;">​</a></h2><h3 id="开始截图" tabindex="-1">开始截图 <a class="header-anchor" href="#开始截图" aria-label="Permalink to &quot;开始截图&quot;">​</a></h3><p>Wing Shot 支持多种方式启动截图：</p><ul><li><strong>快捷键截图</strong>：配置并使用全局快捷键（推荐方式），可在任何场景下快速唤起</li><li><strong>托盘菜单</strong>：右键点击系统托盘图标，选择相应的截图选项</li><li><strong>主界面</strong>：在快捷功能页面点击对应的截图按钮</li></ul><h3 id="截图模式" tabindex="-1">截图模式 <a class="header-anchor" href="#截图模式" aria-label="Permalink to &quot;截图模式&quot;">​</a></h3><p>Wing Shot 提供多种截图模式，满足不同的使用需求：</p><ul><li><strong>区域截图</strong>：自由框选屏幕任意区域进行截图，支持智能窗口识别</li><li><strong>窗口截图</strong>：自动识别并捕获当前窗口的完整内容</li><li><strong>全屏截图</strong>：一键截取整个屏幕画面</li><li><strong>滚动截图</strong>：通过手动或自动滚动截取窗口中的滚动内容</li><li><strong>焦点窗口截图</strong>：快速截取当前活动窗口</li></ul><h3 id="智能窗口识别" tabindex="-1">智能窗口识别 <a class="header-anchor" href="#智能窗口识别" aria-label="Permalink to &quot;智能窗口识别&quot;">​</a></h3><p>在区域截图模式下，Wing Shot 能够自动识别屏幕上的窗口和元素边界：</p><ul><li>移动鼠标时，会自动高亮当前鼠标悬停的窗口或元素</li><li>点击即可快速选中该区域，无需手动调整边界</li><li>按住鼠标拖动可以自由框选任意大小的区域</li></ul><h2 id="标注编辑功能" tabindex="-1">标注编辑功能 <a class="header-anchor" href="#标注编辑功能" aria-label="Permalink to &quot;标注编辑功能&quot;">​</a></h2><p>完成截图区域选择后，会进入标注编辑模式。Wing Shot 提供了丰富的标注工具，帮助您快速为截图添加说明和标记。</p><h3 id="标注工具栏" tabindex="-1">标注工具栏 <a class="header-anchor" href="#标注工具栏" aria-label="Permalink to &quot;标注工具栏&quot;">​</a></h3><p>编辑界面提供了以下标注工具：</p><ul><li><strong>矩形/圆形</strong>：绘制矩形或圆形框，突出重点区域</li><li><strong>箭头/直线</strong>：添加箭头或直线，指示关键信息</li><li><strong>文字标注</strong>：在截图上添加文字说明</li><li><strong>画笔</strong>：自由绘制，标记任意形状</li><li><strong>马赛克</strong>：对敏感信息进行模糊处理</li><li><strong>序号标记</strong>：自动添加序号，适合制作教程步骤</li><li><strong>撤销/重做</strong>：快速回退或恢复编辑操作</li></ul><h3 id="编辑技巧" tabindex="-1">编辑技巧 <a class="header-anchor" href="#编辑技巧" aria-label="Permalink to &quot;编辑技巧&quot;">​</a></h3><ul><li><strong>颜色选择</strong>：每个标注工具都支持自定义颜色，满足不同的标注需求</li><li><strong>粗细调节</strong>：可以调整线条的粗细和文字的大小</li><li><strong>移动和调整</strong>：已添加的标注可以随时选中、移动或调整大小</li><li><strong>删除标注</strong>：选中标注后按 Delete 键或使用橡皮擦工具即可移除</li></ul><h2 id="保存和分享" tabindex="-1">保存和分享 <a class="header-anchor" href="#保存和分享" aria-label="Permalink to &quot;保存和分享&quot;">​</a></h2><p>完成截图编辑后，Wing Shot 提供了多种保存和分享方式：</p><h3 id="复制到剪贴板" tabindex="-1">复制到剪贴板 <a class="header-anchor" href="#复制到剪贴板" aria-label="Permalink to &quot;复制到剪贴板&quot;">​</a></h3><p>点击<strong>复制</strong>按钮或使用快捷键，将截图复制到系统剪贴板，可直接粘贴到：</p><ul><li>聊天工具（微信、QQ、钉钉等）</li><li>文档编辑器（Word、Excel、PowerPoint 等）</li><li>图片编辑软件</li><li>网页输入框</li></ul><h3 id="保存为文件" tabindex="-1">保存为文件 <a class="header-anchor" href="#保存为文件" aria-label="Permalink to &quot;保存为文件&quot;">​</a></h3><p>点击<strong>保存</strong>按钮，将截图保存为图片文件：</p><ul><li>支持自定义保存路径</li><li>支持多种图片格式（PNG、JPG、WEBP、AVIF、JXL 等）</li><li>可在设置中配置默认保存位置和文件命名规则</li></ul><h3 id="固定到屏幕" tabindex="-1">固定到屏幕 <a class="header-anchor" href="#固定到屏幕" aria-label="Permalink to &quot;固定到屏幕&quot;">​</a></h3><p>截图时点击<strong>固定到屏幕</strong>工具，将截图作为悬浮窗固定在屏幕上：</p><ul><li>适合需要对照参考的场景</li><li>悬浮窗可以自由移动和调整大小</li><li>可以同时固定多张截图</li><li>右键点击悬浮窗可以关闭或进行其他操作</li></ul><h2 id="托盘菜单" tabindex="-1">托盘菜单 <a class="header-anchor" href="#托盘菜单" aria-label="Permalink to &quot;托盘菜单&quot;">​</a></h2><p>右键点击系统托盘中的 Wing Shot 图标，可以快速访问常用功能：</p><p><img src="'+s+'" alt="托盘菜单"></p><h2 id="个性化设置" tabindex="-1">个性化设置 <a class="header-anchor" href="#个性化设置" aria-label="Permalink to &quot;个性化设置&quot;">​</a></h2><h3 id="快捷键配置" tabindex="-1">快捷键配置 <a class="header-anchor" href="#快捷键配置" aria-label="Permalink to &quot;快捷键配置&quot;">​</a></h3><p>在主界面的<strong>快捷功能</strong>页面，您可以为各项功能配置全局快捷键：</p><ol><li>找到需要配置快捷键的功能</li><li>点击右侧的按键配置按钮</li><li>录入您想要的快捷键组合</li><li>确认后即可生效</li></ol><p>建议为常用功能设置易于记忆的快捷键，提高工作效率。</p><h3 id="插件管理" tabindex="-1">插件管理 <a class="header-anchor" href="#插件管理" aria-label="Permalink to &quot;插件管理&quot;">​</a></h3><p>Wing Shot 采用插件化设计，您可以根据需求安装或卸载功能插件：</p><ol><li>在侧边栏点击<strong>个性化</strong>下的<strong>插件</strong></li><li>浏览可用的插件列表</li><li>点击<strong>安装</strong>按钮启用需要的功能</li><li>不需要的插件可以点击<strong>卸载</strong>移除</li></ol><p>了解更多插件信息，请查看<a href="/guide/personalization/plugin">插件管理</a>。</p><h2 id="获取帮助" tabindex="-1">获取帮助 <a class="header-anchor" href="#获取帮助" aria-label="Permalink to &quot;获取帮助&quot;">​</a></h2><p>您可以在 Wing Shot 的用户社区更多的了解 Wing Shot 或解决使用上遇到的问题。</p><p>加入我们：<a href="/community/">社区交流</a></p>',52)])])}const _=i(h,[["render",g]]);export{q as __pageData,_ as default};
